export type ProjectExecutionPanel = "summary" | "work" | "quality" | "procurement" | "draws";
type ExecutionAction<Payload> = (payload: Payload) => void | Promise<void>;

export interface ProjectAssigneeOption {
  readonly id: string;
  readonly label: string;
  readonly type: ProjectAssignmentCreatePayload["assigneeType"];
}

export interface ProjectExecutionActions {
  readonly onCreateAssignment?: ExecutionAction<ProjectAssignmentCreatePayload>;
  readonly onUpdateAssignment?: ExecutionAction<ProjectAssignmentUpdatePayload>;
  readonly onCreateMilestone?: ExecutionAction<ProjectMilestoneCreatePayload>;
  readonly onUpdateMilestone?: ExecutionAction<ProjectMilestoneUpdatePayload>;
  readonly onCreateInspection?: ExecutionAction<ProjectInspectionCreatePayload>;
  readonly onUpdateInspection?: ExecutionAction<ProjectInspectionUpdatePayload>;
  readonly onCreatePunchItem?: ExecutionAction<ProjectPunchItemCreatePayload>;
  readonly onUpdatePunchItem?: ExecutionAction<ProjectPunchItemUpdatePayload>;
  readonly onCreateBid?: ExecutionAction<ProjectBidCreatePayload>;
  readonly onUpdateBid?: ExecutionAction<ProjectBidUpdatePayload>;
  readonly onCreateCommitment?: ExecutionAction<ProjectCommitmentCreatePayload>;
  readonly onUpdateCommitment?: ExecutionAction<ProjectCommitmentUpdatePayload>;
  readonly onCreateChangeOrder?: ExecutionAction<ProjectChangeOrderCreatePayload>;
  readonly onUpdateChangeOrder?: ExecutionAction<ProjectChangeOrderUpdatePayload>;
  readonly onCreatePurchaseOrder?: ExecutionAction<ProjectPurchaseOrderCreatePayload>;
  readonly onUpdatePurchaseOrder?: ExecutionAction<ProjectPurchaseOrderUpdatePayload>;
  readonly onCreateVendor?: ExecutionAction<ProjectVendorCreatePayload>;
  readonly onUpdateVendor?: ExecutionAction<ProjectVendorUpdatePayload>;
  readonly onCreateDrawRequest?: ExecutionAction<ProjectDrawRequestCreatePayload>;
  readonly onUpdateDrawRequest?: ExecutionAction<ProjectDrawRequestUpdatePayload>;
  readonly onCreateDrawItem?: ExecutionAction<ProjectDrawRequestItemCreatePayload>;
  readonly onUpdateDrawItem?: ExecutionAction<ProjectDrawRequestItemUpdatePayload>;
}

export interface ProjectExecutionWorkspaceProps extends ProjectExecutionActions {
  readonly detail: ProjectExecutionDetail;
  readonly activePanel?: ProjectExecutionPanel;
  readonly onPanelChange?: (panel: ProjectExecutionPanel) => void;
  readonly assigneeOptions?: readonly ProjectAssigneeOption[];
  readonly readOnly?: boolean;
  /** Limit the workspace to these panels (the section navigation is hidden when only one remains). */
  readonly panels?: readonly ProjectExecutionPanel[];
}

function label(value: string): string { return value.replace(/_/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase()); }
function dateValue(value: string): IsoDate | null { return value ? value as IsoDate : null; }
function decimalValue(value: string): DecimalString { return value as DecimalString; }
function dateLabel(value: string | null | undefined): string { if (!value) return "—"; const date = new Date(`${value.slice(0, 10)}T00:00:00`); return Number.isNaN(date.getTime()) ? value : new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }).format(date); }
function statusTone(value: string): string { return value === "complete" || value === "approved" || value === "paid" || value === "accepted" ? "is-positive" : value === "blocked" || value === "failed" || value === "submitted" ? "is-warning" : value === "cancelled" || value === "void" ? "is-muted" : ""; }
function Status({ value }: { value: string }) { return <span className={`projects-status ${statusTone(value)}`}>{label(value)}</span>; }
function Field({ label: fieldLabel, children }: { label: string; children: ReactNode }) { return <label className="projects-execution-field"><span>{fieldLabel}</span>{children}</label>; }
function FormError({ message }: { message?: string }) { return message ? <div className="projects-error projects-execution-error" role="alert"><CircleAlert size={16} /><span>{message}</span></div> : null; }
function Coverage({ coverage }: { coverage: string }) { const message = coverage === "complete" ? "Verified QBO coverage" : coverage === "partial" ? "Partial QBO coverage" : "QBO actuals unavailable"; return <span className={`projects-execution-coverage ${coverage === "complete" ? "is-positive" : coverage === "partial" ? "is-warning" : "is-muted"}`}><Landmark size={14} />{message}</span>; }

function StatusAction({ value, options, onSave, disabled }: { value: string; options: readonly string[]; onSave?: (status: string) => void | Promise<void>; disabled?: boolean }) {
  const [next, setNext] = useState(value);
  if (!onSave) return <Status value={value} />;
  return <span className="projects-execution-status-action"><select aria-label="Status" value={next} onChange={(event) => setNext(event.currentTarget.value)} disabled={disabled}>{options.map((option) => <option key={option} value={option}>{label(option)}</option>)}</select><button type="button" className="projects-button projects-button-secondary" onClick={() => onSave(next)} disabled={disabled}>Save</button></span>;
}

export function ProjectExecutionSummary({ detail }: { detail: ProjectExecutionDetail }) {
  const totals = detail.totals;
  return <section className="projects-panel projects-execution-summary" aria-label="Execution financial summary"><div className="projects-panel-heading"><h3>Execution control</h3><Coverage coverage={totals.actualCoverage} /></div><div className="projects-execution-metric-grid"><div><span>Original budget</span><strong>{formatMoney(totals.originalBudgetCents, totals.currency)}</strong></div><div><span>Revised budget</span><strong>{formatMoney(totals.revisedBudgetCents, totals.currency)}</strong></div><div><span>Commitments</span><strong>{formatMoney(totals.commitmentCents, totals.currency)}</strong></div><div><span>QBO actual</span><strong>{formatMoney(totals.actualCents ?? undefined, totals.currency)}</strong></div><div><span>Unspent commitment</span><strong>{formatMoney(totals.unspentCommitmentCents ?? undefined, totals.currency)}</strong></div><div><span>Remaining</span><strong>{formatMoney(totals.remainingCents ?? undefined, totals.currency)}</strong></div></div></section>;
}

export function ProjectAssignmentForm({ projectId, assigneeOptions = [], initial, onSubmit, onUpdate, disabled = false }: { projectId: string; assigneeOptions?: readonly ProjectAssigneeOption[]; initial?: ProjectAssignment; onSubmit?: ExecutionAction<ProjectAssignmentCreatePayload>; onUpdate?: ExecutionAction<ProjectAssignmentUpdatePayload>; disabled?: boolean }) {
  const [assignee, setAssignee] = useState(initial ? assigneeOptions.find((option) => option.id === initial.assigneeRef)?.label ?? "" : "");
  const [role, setRole] = useState(initial?.role ?? "");
  const [status, setStatus] = useState<string>(initial?.status ?? "assigned");
  const [formError, setFormError] = useState<string>();
  const submit = (event: FormEvent) => { event.preventDefault(); const option = assigneeOptions.find((item) => item.label.toLowerCase() === assignee.trim().toLowerCase() || item.id === assignee.trim()); if (!option || !role.trim()) { setFormError("Choose a named assignee and enter a role."); return; } setFormError(undefined); if (initial && onUpdate) void onUpdate({ assignmentId: initial.id, assigneeType: option.type, assigneeRef: option.id as ProjectAssignmentUpdatePayload["assigneeRef"], role: role.trim(), status: status as ProjectAssignmentUpdatePayload["status"] }); else if (onSubmit) void onSubmit({ projectId: projectId as ProjectAssignmentCreatePayload["projectId"], assigneeType: option.type, assigneeRef: option.id as ProjectAssignmentCreatePayload["assigneeRef"], role: role.trim() }); };
  return <form className="projects-execution-form" onSubmit={submit} aria-label={initial ? "Edit assignment" : "Add project assignment"}><div className="projects-execution-form-heading"><h4>{initial ? "Edit assignment" : "Assign work"}</h4></div><FormError message={formError} /><div className="projects-execution-form-grid"><Field label="Assignee"><input list="project-assignee-options" value={assignee} onChange={(event) => setAssignee(event.currentTarget.value)} placeholder="Search by name" disabled={disabled} /><datalist id="project-assignee-options">{assigneeOptions.map((option) => <option key={option.id} value={option.label}>{label(option.type)}</option>)}</datalist></Field><Field label="Role"><input value={role} onChange={(event) => setRole(event.currentTarget.value)} disabled={disabled} /></Field>{initial && <Field label="Status"><select value={status} onChange={(event) => setStatus(event.currentTarget.value)} disabled={disabled}>{["assigned", "accepted", "in_progress", "complete", "declined", "cancelled"].map((option) => <option key={option} value={option}>{label(option)}</option>)}</select></Field>}</div><button className="projects-button projects-button-primary" type="submit" disabled={disabled || assigneeOptions.length === 0}>{initial ? "Save assignment" : "Assign work"}</button></form>;
}

export function ProjectVendorForm({ initial, onCreate, onUpdate, disabled = false }: { initial?: ProjectVendor; onCreate?: ExecutionAction<ProjectVendorCreatePayload>; onUpdate?: ExecutionAction<ProjectVendorUpdatePayload>; disabled?: boolean }) {
  const [name, setName] = useState(initial?.name ?? "");
  const [status, setStatus] = useState<string>(initial?.status ?? "active");
  const [notes, setNotes] = useState(initial?.notes ?? "");
  const [formError, setFormError] = useState<string>();
  const submit = (event: FormEvent) => { event.preventDefault(); if (!name.trim()) { setFormError("Vendor name is required."); return; } setFormError(undefined); if (initial && onUpdate) void onUpdate({ vendorId: initial.id, name: name.trim(), status: status as ProjectVendorUpdatePayload["status"], notes: notes || null }); else if (onCreate) void onCreate({ name: name.trim(), notes: notes || null }); };
  return <form className="projects-execution-form" onSubmit={submit} aria-label={initial ? "Edit vendor" : "Add vendor"}><div className="projects-execution-form-heading"><h4>{initial ? "Edit vendor" : "Add vendor"}</h4></div><FormError message={formError} /><div className="projects-execution-form-grid"><Field label="Name"><input value={name} onChange={(event) => setName(event.currentTarget.value)} disabled={disabled} /></Field>{initial && <Field label="Status"><select value={status} onChange={(event) => setStatus(event.currentTarget.value)} disabled={disabled}>{["active", "inactive", "on_hold"].map((option) => <option key={option} value={option}>{label(option)}</option>)}</select></Field>}<Field label="Notes"><input value={notes} onChange={(event) => setNotes(event.currentTarget.value)} disabled={disabled} /></Field></div><button className="projects-button projects-button-primary" type="submit" disabled={disabled}>{initial ? "Save vendor" : "Add vendor"}</button></form>;
}

