export function ProjectBidForm({ projectId, currency, vendors, initial, onCreate, onUpdate, disabled = false }: { projectId: string; currency: string; vendors: ProjectExecutionDetail["vendors"]; initial?: ProjectBid; onCreate?: ExecutionAction<ProjectBidCreatePayload>; onUpdate?: ExecutionAction<ProjectBidUpdatePayload>; disabled?: boolean }) {
  const [vendorId, setVendorId] = useState<string>(initial?.vendorId ?? vendors[0]?.id ?? "");
  const [amount, setAmount] = useState(initial ? formatInputValue(initial.amountCents) : "");
  const [status, setStatus] = useState<string>(initial?.status ?? "draft");
  const [formError, setFormError] = useState<string>();
  const submit = (event: FormEvent) => { event.preventDefault(); try { const cents = parseMoneyInput(amount, "Bid amount").cents; if (!vendorId) throw new Error("Choose a vendor."); setFormError(undefined); if (initial && onUpdate) void onUpdate({ bidId: initial.id, vendorId: vendorId as ProjectBidUpdatePayload["vendorId"], amountCents: cents, status: status as ProjectBidUpdatePayload["status"] }); else if (onCreate) void onCreate({ projectId: projectId as ProjectBidCreatePayload["projectId"], vendorId: vendorId as ProjectBidCreatePayload["vendorId"], amountCents: cents, notes: null }); } catch (error) { setFormError(error instanceof Error ? error.message : "Enter a valid bid."); } };
  return <form className="projects-execution-form" onSubmit={submit} aria-label={initial ? "Edit bid" : "Add bid"}><div className="projects-execution-form-heading"><h4>{initial ? "Edit bid" : "Add bid"}</h4></div><FormError message={formError} /><div className="projects-execution-form-grid"><Field label="Vendor"><select value={vendorId} onChange={(event) => setVendorId(event.currentTarget.value)} disabled={disabled}><option value="">Choose vendor</option>{vendors.map((vendor) => <option key={vendor.id} value={vendor.id}>{vendor.name}</option>)}</select></Field><Field label={`Amount (${currency})`}><input inputMode="decimal" value={amount} onChange={(event) => setAmount(event.currentTarget.value)} placeholder={formatInputValue("0")} disabled={disabled} /></Field>{initial && <Field label="Status"><select value={status} onChange={(event) => setStatus(event.currentTarget.value)} disabled={disabled}>{["draft", "submitted", "shortlisted", "accepted", "rejected", "withdrawn"].map((option) => <option key={option} value={option}>{label(option)}</option>)}</select></Field>}</div><button className="projects-button projects-button-primary" type="submit" disabled={disabled}>{initial ? "Save bid" : "Add bid"}</button></form>;
}

export function ProjectCommitmentForm({ projectId, currency, initial, onSubmit, onUpdate, disabled = false }: { projectId: string; currency: string; initial?: ProjectCommitment; onSubmit?: ExecutionAction<ProjectCommitmentCreatePayload>; onUpdate?: ExecutionAction<ProjectCommitmentUpdatePayload>; disabled?: boolean }) {
  const [description, setDescription] = useState(initial?.description ?? "");
  const [amount, setAmount] = useState(initial ? formatInputValue(initial.originalCents) : "");
  const [approvedChange, setApprovedChange] = useState(initial ? formatInputValue(initial.approvedChangeCents) : "0");
  const [status, setStatus] = useState<string>(initial?.status ?? "draft");
  const [formError, setFormError] = useState<string>();
  const submit = (event: FormEvent) => { event.preventDefault(); try { if (!description.trim()) throw new Error("Commitment description is required."); const cents = parseMoneyInput(amount, "Original commitment").cents; const change = parseMoneyInput(approvedChange, "Approved change").cents; if (initial && onUpdate) void onUpdate({ commitmentId: initial.id, description: description.trim(), originalCents: cents, approvedChangeCents: change, status: status as ProjectCommitmentUpdatePayload["status"] }); else if (onSubmit) void onSubmit({ projectId: projectId as ProjectCommitmentCreatePayload["projectId"], description: description.trim(), originalCents: cents, currency: currency as ProjectCommitmentCreatePayload["currency"] }); setFormError(undefined); } catch (error) { setFormError(error instanceof Error ? error.message : "Enter valid commitment amounts."); } };
  return <form className="projects-execution-form" onSubmit={submit} aria-label={initial ? "Edit commitment" : "Add project commitment"}><div className="projects-execution-form-heading"><h4>{initial ? "Edit commitment" : "Record commitment"}</h4></div><FormError message={formError} /><div className="projects-execution-form-grid"><Field label="Description"><input value={description} onChange={(event) => setDescription(event.currentTarget.value)} disabled={disabled} /></Field><Field label={`Original amount (${currency})`}><input inputMode="decimal" value={amount} onChange={(event) => setAmount(event.currentTarget.value)} placeholder={formatInputValue("0")} disabled={disabled} /></Field>{initial && <><Field label={`Approved change (${currency})`}><input inputMode="decimal" value={approvedChange} onChange={(event) => setApprovedChange(event.currentTarget.value)} disabled={disabled} /></Field><Field label="Status"><select value={status} onChange={(event) => setStatus(event.currentTarget.value)} disabled={disabled}>{["draft", "approved", "closed", "void"].map((option) => <option key={option} value={option}>{label(option)}</option>)}</select></Field></>}</div><button className="projects-button projects-button-primary" type="submit" disabled={disabled}>Save commitment</button></form>;
}

